418	void ProjectVersionStore::recover_uncommitted()
419	{
420	    const std::set<std::string> committed(m_committed_ids.begin(), m_committed_ids.end());
421	    // The lock proves no earlier process can still be loading from these
422	    // disposable directories. Orca never uses the retained store as backup.
423	    for (const auto& entry : fs::directory_iterator(m_root / "materialized"))
424	        fs::remove_all(entry.path());
425	    for (const auto& entry : fs::directory_iterator(m_root / "pending"))
426	        fs::remove_all(entry.path());
427	    for (const auto& entry : fs::directory_iterator(m_root / "versions"))
428	        if (entry.is_directory() && !committed.count(entry.path().filename().string()))
429	            fs::remove_all(entry.path());
