244	void ProjectPersistence::adopt_current_project(bool in_place_reset)
245	{
246	    m_attached_aux_dir = m_workspace.auxiliary_data_dir();
247	    m_attached         = true;
248	    m_draft.clear();
249	
250	    if (in_place_reset) {
251	        // A full in-place reset is a new project boundary: earlier state does
252	        // not carry into it.
253	        if (m_config.managed_root.empty()) {
254	            std::error_code ec;
255	            fs::remove_all(jusprin_data_dir(), ec);
256	        }
257	        start_fresh_identity();
258	        return;
259	    }
260	
261	    // An external archive can carry the old auxiliary document. Read it once
262	    // for migration; managed snapshots never write authoritative state there.
263	    const fs::path legacy_state = fs::path(m_attached_aux_dir) / kJusPrinDirName / kStateFileName;
264	    const std::string state_text = read_file(m_config.managed_root.empty() ? fs::path(state_file_path()) : legacy_state);
265	    if (state_text.empty()) {
266	        start_fresh_identity();
267	        return;
268	    }
269	
270	    ProjectStateDocument loaded;
271	    const ProjectStateDocument::LoadResult result = loaded.load(state_text);
272	    if (result == ProjectStateDocument::LoadResult::Corrupt) {
273	        // Keep the unreadable file for inspection, then start over.
274	        std::error_code ec;
275	        fs::rename(legacy_state, legacy_state.string() + ".corrupt", ec);
276	        start_fresh_identity();
277	        return;
278	    }
279	    m_document = std::move(loaded);
280	
281	    // The recovery mirror may hold state newer than the last explicit save
282	    // (messages, approvals, a partial reply from before a crash).
283	    const std::string recovery = m_config.managed_root.empty() ? recovery_dir() :
284	        (m_config.recovery_root.empty() ? std::string() :
285	            (fs::path(m_config.recovery_root) / m_document.project_id()).string());
286	    if (!recovery.empty()) {
287	        const std::string mirror_text = read_file(fs::path(recovery) / kStateFileName);
288	        if (!mirror_text.empty()) {
289	            ProjectStateDocument mirror;
290	            if (mirror.load(mirror_text) != ProjectStateDocument::LoadResult::Corrupt &&
291	                mirror.project_id() == m_document.project_id() && mirror.doc_revision() > m_document.doc_revision())
292	                m_document = std::move(mirror);
293	        }
294	        if (m_config.managed_root.empty())
295	            load_recovery_meta();
296	    }
297	
298	    if (!m_config.managed_root.empty()) {
299	        // A copied or reopened external archive is an import, even when it
300	        // carries an identity that already has a managed head on this host.
301	        if (fs::exists(fs::path(m_config.managed_root) / m_document.project_id() / "HEAD"))
302	            m_document.fork_identity("p-" + m_config.uuid(), m_config.clock());
303	        const fs::path old_attachments = fs::path(m_attached_aux_dir) / kJusPrinDirName / "attachments";
304	        const fs::path local_attachments = fs::path(jusprin_data_dir()) / "attachments";
305	        if (fs::is_directory(old_attachments)) {
306	            for (const auto& entry : fs::recursive_directory_iterator(old_attachments)) {
307	                const fs::path target = local_attachments / fs::relative(entry.path(), old_attachments);
308	                if (entry.is_directory())
309	                    fs::create_directories(target);
310	                else if (entry.is_regular_file()) {
311	                    fs::create_directories(target.parent_path());
312	                    fs::copy_file(entry.path(), target, fs::copy_options::overwrite_existing);
313	                }
314	            }
315	        }
316	    }
317	
318	    // A stream or run interrupted by the crash/restart cannot resume.
319	    m_document.normalize_interrupted_state();
320	    if (!m_config.managed_root.empty()) {
321	        m_draft = m_document.draft();
322	    }
323	
324	    m_dirty = true;
325	    flush();
326	    notify_document_replaced();
327	}
