288	        // listeners, so the initial document reaches the pane too.
289	        m_persistence->attach();
290	        m_autosave = std::make_unique<Workspace::ProjectAutosave>(
291	            *plater, *m_persistence, *m_workspace,
292	            std::filesystem::path(data_dir()) / "jusprin" / "projects");
293	        auto& project_host = m_agent_pane->web_view().host();
294	        project_host.set_restore_points_provider([this] {
295	            nlohmann::json points = nlohmann::json::array();
296	            if (!m_autosave)
297	                return points;
298	            // Keep the first model saved at a boundary: later model-only saves
299	            // with the same change sequence must not move its restore target.
300	            std::map<std::uint64_t, std::string> by_change;
301	            const auto versions = m_autosave->history();
302	            const auto current = m_autosave->current_version();
303	            const auto head = std::find_if(versions.begin(), versions.end(), [&current](const auto& version) {
304	                return version.id == current;
305	            });
306	            const auto changes = m_persistence->document().changes();
307	            const std::uint64_t latest_change_seq = changes.empty() ? 0 : changes.back().seq;
308	            // The head needs no revert action while it still describes the
309	            // latest change; once a newer edit is logged it becomes useful.
310	            const std::uint64_t current_change_seq = head != versions.end() && head->change_seq == latest_change_seq
311	                ? head->change_seq : 0;
312	            for (const auto& version : versions)
313	                if (version.change_seq != 0 && version.change_seq != current_change_seq)
314	                    by_change.emplace(version.change_seq, version.id);
315	            for (const auto& [seq, id] : by_change)
316	                points.push_back({{"changeSeq", seq}, {"versionId", id}});
317	            return points;
318	        });
319	        project_host.set_page_message_handler([this](const std::string& type, const nlohmann::json& payload) {
320	            if (type != Agent::Protocol::kShellAction || !payload.is_object())
321	                return false;
322	            const std::string action = payload.value("action", std::string());
323	            if (action == "collapse_agent_pane") {
324	                // Hiding a wxWebView from inside its own script-message
325	                // callback can stall its platform message pump. Collapse on
326	                // the next native turn, after this handler has returned.
327	                m_frame->CallAfter([this] {
328	                    if (m_installed && !m_agent_pane_collapsed)
329	                        toggle_agent_pane();
330	                });
331	                return true;
332	            }
333	            if (action != "revert_to_here")
334	                return false;
335	            const std::string id = payload.value("versionId", std::string());
336	            const auto versions = m_autosave->history();
337	            const auto found = std::find_if(versions.begin(), versions.end(), [&id](const auto& version) {
338	                return version.id == id && version.change_seq != 0;
339	            });
340	            if (found == versions.end() || !m_autosave->restore(id)) {
341	                wxMessageBox(_L("This saved version couldn't be restored. Try again from Version history."),
342	                             _L("Revert failed"), wxOK | wxICON_ERROR, m_frame);
343	            }
344	            m_agent_pane->web_view().host().refresh_page_state();
345	            return true;
346	        });
347	        m_agent_pane->web_view().host().set_turn_boundary_callback([this] { m_autosave->save_now(); });
348	        Slic3r::set_backup_suspended(true);
349	        m_status_row->set_autosave(m_autosave.get());
350	        plater->set_before_project_release([this] {
351	            if (!m_autosave || !m_autosave->save_now())
352	                return false;
353	            m_autosave->ensure_current_preview();
354	            return true;
355	        });
356	        plater->set_external_project_open_handler([this](const Plater::fs_path& path) {
357	#ifdef _WIN32
358	            const std::filesystem::path source(path.wstring());
359	#else
360	            const std::filesystem::path source(path.string());
361	#endif
362	            if (!m_autosave)
363	                return false;
364	            const auto matches = m_autosave->projects_for_source(source);
365	            if (matches.empty())
366	                return false;
367	            const bool current = matches.front() == m_persistence->document().project_id();
368	            const ReimportDecision decision = m_reimport_confirmation ? m_reimport_confirmation() : [this, &matches, current] {
369	                const wxString message = current ?
370	                    _L("This file is already open as a project. Continue working in it, or create a new project from this file.") :
371	                    matches.size() > 1 ?
372	                    _L("You've opened this file before. Open the most recently updated project or create another project from this file.") :
373	                    _L("You've opened this file before. Open the existing project to continue where you left off, "
374	                       "or create a new project from this file.");
375	                wxMessageDialog dialog(m_frame,
376	                    message, _L("Previously opened file"), wxYES_NO | wxCANCEL | wxICON_QUESTION);
377	                dialog.SetYesNoLabels(current ? _L("Continue current project") :
378	                                      matches.size() > 1 ? _L("Open most recent project") : _L("Open existing project"),
379	                                      _L("Create new project"));
380	                const int answer = dialog.ShowModal();
381	                return answer == wxID_YES ? ReimportDecision::OpenExisting :
382	                       answer == wxID_NO ? ReimportDecision::CreateNew : ReimportDecision::Cancel;
383	            }();
384	            if (decision == ReimportDecision::CreateNew)
385	                return false;
386	            if (decision == ReimportDecision::OpenExisting) {
387	                if (!m_autosave->open_managed_project(matches.front()))
388	                    wxMessageBox(_L("The project couldn't be opened. Try again."), _L("Couldn't open project"),
389	                                 wxOK | wxICON_ERROR, m_frame);
390	                else
391	                    m_frame->select_tab(size_t(MainFrame::tp3DEditor));
392	            }
393	            return true;
394	        });
395	        m_agent_pane->web_view().host().tools().set_version_callbacks(
396	            [this](const Agent::ToolActivity&) {
397	                const std::string before = m_autosave->pin_current();
398	                if (before.empty())
399	                    throw std::runtime_error("Couldn't save the project. The action was not run.");
400	                return before;
401	            },
402	            [this](const Agent::ToolActivity& activity, const std::string& before) {
403	                const char* outcome = activity.state == Agent::ToolState::Succeeded ? "succeeded" :
404	                                      activity.state == Agent::ToolState::Cancelled ? "cancelled" : "failed";
405	                m_autosave->record_agent_operation(activity.action_id, activity.tool, outcome, before);
406	            });
407	        m_agent_pane->web_view().host().tools().set_document_boundary_callback(
408	            [this](const Agent::ToolActivity&) {
409	                if (!m_autosave->save_now())
410	                    throw std::runtime_error("The action ran, but its changes couldn't be saved.");
411	            });
412	
413	        // One shell-owned pump continues throughout WebView page reloads.
414	        // The page handshake gates delivery, not native MCP execution.
415	        m_runtime_timer.Start(33);
416	
417	        // Home is a fork-owned panel beside the Notebook, not one of its pages.
418	        // The Notebook keeps every page it had, so upstream keeps the meaning
419	        // of its indices: the dialog parents that ask for page 0, the
420	        // predicates that key off GetSelection(), and any future cast of a
421	        // page all still find the window they expect. The shell owns only
422	        // which of the two is on screen for tpHome.
423	        m_home = new Home::HomeWebView(&frame, *m_theme, frame);
424	        m_home->backend().set_autosave(m_autosave.get());
425	        m_home->Hide();

