  3	// The current semantic document of a JusPrin project: conversations,
  4	// their messages and tool activity records, attachments, and the
  5	// manufacturing history (builds, exported copies, physical prints).
  6	// Managed projects save it independently of model checkpoints in
  7	// current-state.json. Legacy imports can still read auxiliary state.json.
  8	//
  9	// The document is backed by one JSON tree that is edited in place, so
 10	// optional fields written by other (newer) builds survive a load-edit-save
 11	// cycle untouched. Every entry carries a monotonically increasing global
 12	// sequence number `seq`, which orders entries across every conversation.
 13	// GUI-free.
 14	
 15	#include "AgentProtocol.hpp"
 16	#include "ManufacturingHistory.hpp"
 17	#include "ToolExecution.hpp"
 18	#include "slic3r/GUI/JusPrin/Workspace/Workspace.hpp"
 19	
 20	#include <nlohmann/json.hpp>
 21	
 22	#include <functional>
 23	#include <optional>
 24	#include <string>
 25	#include <vector>
 26	
 27	namespace Slic3r::GUI::JusPrin::Agent {
 28	
 29	struct ConversationInfo
 30	{
 31	    std::string id;
 32	    std::string title;
 33	    std::string created_at;
 34	    std::string updated_at;
 35	    std::string preview;
 36	    std::uint64_t activity_seq{0};
 37	};
 38	
 39	// One entry of the change log: an edit the workspace reported, stored raw.
 40	// The Agent page groups consecutive entries for display; nothing here merges,
 41	// words, or delays them, so the grouping can change without touching saved
 42	// data.
 43	struct ChangeEntry
 44	{
 45	    std::uint64_t seq{0};
 46	    std::string   created_at;
 47	    std::string   kind;            // step|undo|redo|setting|preset
 48	    std::string   actor;           // person|agent
 49	    std::string   label;           // as the workspace reported it; may be empty
 50	    std::string   location;        // optional place of a hand edit, when known
 51	    std::string   from, to, preset; // setting only
 52	    std::string   conversation_id; // the conversation active at the time
 53	    std::string   after_id;        // the conversation item it follows; empty before the first
 54	};
 55	
 56	// Metadata for one attachment. The blob lives under
 57	// <JusPrin data dir>/attachments/<id>/<stored_name>; this record is the
 58	// portable, saved description of it. `state` is "staged" while the attachment
 59	// sits in the composer and "sent" once a durable user message owns it.
 60	struct AttachmentRecord
 61	{
 62	    std::string   id;            // "a-<n>", also the blob subdirectory name
 63	    std::uint64_t seq{0};
 64	    std::string   client_id;     // page-supplied stable ID, for resend dedup
 65	    std::string   original_name; // display name as chosen by the user
 66	    std::string   stored_name;   // sanitized file name written to disk
 67	    std::string   kind;          // text|image|svg|pdf|gcode|model|unsupported
 68	    std::string   mime;
 69	    std::uint64_t size_bytes{0};
 70	    std::string   source;        // picker|drop|clipboard|project
 71	    std::string   state;         // staged|sent|error
 72	    std::string   preview_text;  // decoded text preview (may be truncated)
 73	    std::string   preview_data_url; // small image thumbnail data URL
 74	    std::string   summary;       // native, non-binary model summary
 75	    std::string   content_hash;  // opaque content hash, when computed
 76	    std::optional<AgentError> error;
 77	
 78	    // Relative (to the JusPrin data dir) directory holding the blob.
 79	    std::string relative_dir() const { return "attachments/" + id; }
 80	    // Relative path of the blob itself.
 81	    std::string relative_path() const { return relative_dir() + "/" + stored_name; }
 82	};
 83	
 84	// Where a recorded fact came from. A tool never promotes an inferred value to
 85	// confirmed; only an approved write that showed the value on its card does.
 86	enum class Provenance : std::uint8_t { File, Observed, AgentInferred, UserConfirmed };
 87	
 88	// One spelling, shared by the stored document and every tool result.
 89	inline const char* provenance_name(Provenance provenance)
 90	{
 91	    switch (provenance) {
 92	    case Provenance::File: return "file";
 93	    case Provenance::Observed: return "observed";
 94	    case Provenance::UserConfirmed: return "user_confirmed";
 95	    case Provenance::AgentInferred: break;
 96	    }
 97	    return "agent_inferred";
 98	}
 99	
100	inline Provenance provenance_from(const std::string& text)
101	{
102	    if (text == "file") return Provenance::File;
103	    if (text == "observed") return Provenance::Observed;
104	    if (text == "user_confirmed") return Provenance::UserConfirmed;
105	    return Provenance::AgentInferred;
106	}
107	
108	// One answer in the print intent: what the user wants out of this print,
109	// rather than how to slice it. The field vocabulary belongs to the tool that
110	// writes it and validates what it accepts; the store keeps what was written,
111	// where it came from, and when. This is not a conversation's setup_intent,
112	// which restates one delegation in the user's own words.
113	struct IntentField
114	{
115	    std::string   field;
116	    std::string   value;
117	    // Set when the agent has asked about this field and has no answer yet: the
118	    // question it asked, in the words it used. A field with a question and no
119	    // value is what the agent still does not know, which is the only way to
120	    // have that list when the field names are the agent's own invention.
121	    std::string   question;
122	    Provenance    provenance{Provenance::AgentInferred};
123	    std::uint64_t seq{0};
124	    std::string   updated_at;
125	
126	    bool answered() const { return !value.empty(); }
127	};
128	
129	// One decision the agent made and is prepared to defend.
130	struct PlanDecision
131	{
132	    std::string topic;       // orientation, supports, material, ...
133	    std::string statement;   // the decision and its reasoning, in the user's terms
134	    std::string confidence;  // the agent's own confidence in it
135	    std::string alternative; // what else was considered, and why it lost
136	};
137	
138	// The agent's pinned statement of how it means to print this project: what it
139	// decided, what it assumed without being able to check, and what could still
140	// go wrong. The agent's own words, not a description of the configuration --
141	// the configuration is read from the presets, which cannot say why.
142	struct PlanRecord
143	{
144	    std::uint64_t             seq{0};
145	    std::string               updated_at;
146	    std::string               headline;
147	    std::vector<PlanDecision> decisions;
148	    std::vector<std::string>  assumptions;
149	    std::vector<std::string>  risks;
150	};
151	
152	class ProjectStateDocument
153	{
154	public:
155	    static constexpr int kSchemaVersion = 2;
156	
157	    enum class LoadResult { Loaded, Migrated, Corrupt };
158	
159	    ProjectStateDocument();
160	
161	    // Corrupt input keeps a fresh empty document (the caller decides whether
162	    // to adopt a new identity); an older schema is migrated in place.
163	    LoadResult load(const std::string& json_text);
164	    std::string dump() const;
165	    // These fields follow a model version when the person restores history.
166	    // Conversation, audit, drafts, and print facts remain current instead.
167	
168	    // Monotonic per-document change counter, bumped by every mutating call.
169	    // The recovery mirror with the higher value is the newer state.
170	    std::uint64_t doc_revision() const;
171	
172	    bool        has_identity() const;
173	    std::string project_id() const;
174	    std::string lineage_id() const;
175	
176	    // Creates the identity and the first conversation.
177	    void initialize_identity(const std::string& project_id, const std::string& lineage_id, const std::string& timestamp);
178	    // An imported copy starts a distinct managed project while preserving its
179	    // migrated conversation and manufacturing history.
180	    void fork_identity(const std::string& project_id, const std::string& timestamp);
181	    void set_draft(const std::string& draft);
182	    std::string draft() const;
183	
184	    // -- Conversations ------------------------------------------------------
185	    std::vector<ConversationInfo> conversations() const;
186	    std::string                   active_conversation_id() const;
187	    std::string create_conversation(const std::string& title, const std::string& timestamp); // returns id, makes it active
188	    bool        set_active_conversation(const std::string& conversation_id);
189	    bool        needs_conversation_title(const std::string& conversation_id) const;
190	    bool        rename_conversation(const std::string& conversation_id, const std::string& title, bool generated = false);
191	    // The agent's restatement of what this chat asked the setup to be, in the
192	    // user's own words. Written by a settings change, never by talking, and
193	    // kept for the life of the chat: it is the record of a delegation, not a
194	    // description of the current config. Empty until the first change.
195	    std::string setup_intent(const std::string& conversation_id) const;
196	    bool        set_setup_intent(const std::string& conversation_id, const std::string& intent);
197	    // Erases chat content and returns orphaned attachment directories. Builds,
198	    // exported copies and physical prints retain their historical
199	    // conversation IDs.
200	    std::optional<std::vector<std::string>> delete_conversation(const std::string& conversation_id,
201	                                                               const std::string& timestamp);
202	
203	    // -- Messages -----------------------------------------------------------
204	    std::string allocate_message_id();
205	    std::string allocate_action_id();
206	    std::string allocate_attachment_id();
207	
208	    void append_message(const std::string& conversation_id, const ConversationMessage& message, const std::string& timestamp);
209	    bool update_message(const std::string& conversation_id, const ConversationMessage& message);
210	    std::vector<ConversationMessage> messages(const std::string& conversation_id) const;
211	    // The conversation that holds the message, or empty.
212	    std::string conversation_of_message(const std::string& message_id) const;
213	    std::optional<std::string> client_message_lookup(const std::string& client_message_id) const;
214	
215	    // -- Tool activities ----------------------------------------------------
216	    void upsert_activity(const ToolActivity& activity, const std::string& timestamp);
217	    std::vector<ToolActivity> activities() const;
218	    // Marks every non-terminal stored state (a crash mid-run) cancelled and
219	    // every streaming message stopped; returns whether anything changed.
220	    bool normalize_interrupted_state();
221	
222	    // -- Attachments --------------------------------------------------------
223	    // Records are added while staged and flipped to "sent" when a user message
224	    // adopts them. add/update preserve unknown fields written by other builds.
225	    void add_attachment(const AttachmentRecord& record, const std::string& timestamp);
226	    bool update_attachment(const AttachmentRecord& record);
227	    std::vector<AttachmentRecord> attachments() const;
228	    std::optional<AttachmentRecord> find_attachment(const std::string& attachment_id) const;
229	    std::optional<AttachmentRecord> find_attachment_by_client_id(const std::string& client_id) const;
230	    // Removes a staged attachment record; returns its relative_dir for blob
231	    // cleanup, or nullopt when it does not exist or is not staged.
232	    std::optional<std::string> remove_staged_attachment(const std::string& attachment_id);
233	    // Flips the given staged attachments to "sent". IDs that are missing or
234	    // not staged are ignored; returns the IDs that were actually sent.
235	    std::vector<std::string> mark_attachments_sent(const std::vector<std::string>& attachment_ids);
236	
237	    // -- Manufacturing history --------------------------------------------
238	    // Add-only immutable records.
239	    std::string add_build(BuildRecord record, const std::string& timestamp);
240	    std::string add_exported_copy(ExportedCopyRecord record, const std::string& timestamp);
241	    std::string add_physical_print(PhysicalPrintRecord record, const std::string& timestamp);
242	    std::vector<BuildRecord>         builds() const;
243	    std::vector<ExportedCopyRecord>  exported_copies() const;
244	    std::vector<PhysicalPrintRecord> physical_prints() const;
245	    // Ledger size without materializing every record; the shell's status row
246	    // reads this on every project change.
247	    std::size_t                      physical_print_count() const;
248	    std::optional<BuildRecord>       find_build(const std::string& build_id) const;
249	    std::optional<BuildRecord>       latest_build() const;
250

