   329	void ProjectPersistence::notify_document_replaced()
   330	{
   331	    if (m_document_replaced)
   332	        m_document_replaced();
   333	    // A replaced document brings a different manufacturing ledger with it.
   334	    notify_ledger_changed();
   335	}
