602	    for (ModelObject* object : live.objects) {
603	        const int backup_id = live.get_object_backup_id(*object);
604	        const auto found = std::find_if(version.objects.begin(), version.objects.end(), [backup_id](const ObjectResource& item) {
605	            return item.backup_id == backup_id;
606	        });
607	        if (found == version.objects.end() || resources.count(object->id().id))
608	            return;
609	        resources[object->id().id] = *found;
610	        signatures[object->id().id] = signature_of(*object, backup_id);
611	    }
612	    m_last_resources = std::move(resources);
613	    m_last_signatures = std::move(signatures);
614	    m_last_model = std::make_shared<Model>(live);
