617	ProjectVersionStore::Capture ProjectVersionStore::freeze(Model& live, const std::string& version_id,
618	                                                          std::uint64_t revision, std::string semantic_state,
619	                                                          std::string source_path, std::string created_at)
620	{
621	    require(safe_component(version_id), "invalid version id");
622	    const fs::path pending = m_root / "pending" / version_id;
623	    require(fs::exists(pending / "metadata.3mf"), "project metadata was not captured");
624	    require(valid_zip_entry(pending / "metadata.3mf", ""), "project metadata archive is invalid");
625	    publish_document(std::move(semantic_state));
626	    Capture capture;
627	    capture.version = {version_id, revision, 0, std::move(created_at), std::move(source_path), {}};
628	    capture.pending_dir = pending;
629	    capture.frozen = std::make_shared<Model>(live);
630	    for (std::size_t index = 0; index < live.objects.size(); ++index) {
631	        ModelObject& original = *live.objects[index];
632	        ModelObject& object = *capture.frozen->objects[index];
633	        const int backup_id = live.get_object_backup_id(original);
634	        capture.frozen->set_object_backup_id(object, backup_id);
635	        ObjectResource item;
636	        item.object_id = object.id().id;
637	        item.backup_id = backup_id;
638	        for (const ModelVolume* volume : object.volumes)
639	            item.facets += volume->mesh().facets_count();
640	        item.entry = entry_for(object);
641	        const std::string signature = signature_of(object, backup_id);
642	        capture.signatures[item.object_id] = signature;
643	        const auto previous = m_last_resources.find(item.object_id);
644	        const auto old_signature = m_last_signatures.find(item.object_id);
645	        if (previous != m_last_resources.end() && old_signature != m_last_signatures.end() &&
646	            old_signature->second == signature) {
647	            item.resource = previous->second.resource;
648	        } else {
649	            item.resource = {new_id(), item.entry};
650	            capture.changed_objects.push_back(item.object_id);
651	        }
652	        capture.version.objects.push_back(std::move(item));
653	    }
654	    validate_metadata(pending / "metadata.3mf", capture.version);
655	    return capture;
656	}
