670	void ProjectVersionStore::publish(Capture capture)
671	{
672	    require(capture.frozen != nullptr, "capture has no model");
673	    require(m_document_schema == 2, "project document must be durable before a model checkpoint");
674	    const fs::path pending = capture.pending_dir;
675	    validate_metadata(pending / "metadata.3mf", capture.version);
676	    fs::create_directories(pending / "new-resources");
677	    Model subset(*capture.frozen);
678	    for (std::size_t index = subset.objects.size(); index > 0; --index)
679	        if (std::find(capture.changed_objects.begin(), capture.changed_objects.end(),
680	                      subset.objects[index - 1]->id().id) == capture.changed_objects.end())
681	            subset.delete_object(index - 1);
682	    subset.set_backup_path((pending / "writer-private").u8string());
683	    if (!subset.objects.empty()) {
684	        const fs::path changed_file = pending / "changed.3mf";
685	        const std::string changed_path = changed_file.u8string();
686	        StoreParams params;
687	        params.path = changed_path.c_str();
688	        params.model = &subset;
689	        params.config = nullptr;
690	        params.strategy = SaveStrategy::Silence | SaveStrategy::SplitModel | SaveStrategy::SkipAuxiliary | SaveStrategy::Zip64;
691	        require(store_bbs_3mf(params), "changed-object serialization failed");
692	        require(valid_zip_entry(changed_path, ""), "changed-object archive is invalid");
693	        mz_zip_archive input;
694	        mz_zip_zero_struct(&input);
695	        require(open_zip_reader(&input, changed_path), "cannot open changed-object archive");
696	        for (ObjectResource& object : capture.version.objects) {
697	            if (std::find(capture.changed_objects.begin(), capture.changed_objects.end(), object.object_id) ==
698	                capture.changed_objects.end())
699	                continue;
700	            const auto subset_object = std::find_if(subset.objects.begin(), subset.objects.end(), [&object](const ModelObject* item) {
701	                return item->id().id == object.object_id;
702	            });
703	            require(subset_object != subset.objects.end(), "changed object was omitted from the serializer input");
704	            object.resource.entry = entry_for(**subset_object);
705	            const int entry_index = mz_zip_reader_locate_file(&input, object.resource.entry.c_str(), nullptr, 0);
706	            require(entry_index >= 0, "serialized object resource is missing: " + object.resource.entry);
707	            const fs::path target = pending / "new-resources" / (object.resource.id + ".zip");
708	            mz_zip_archive output;
709	            mz_zip_zero_struct(&output);
710	            require(open_zip_writer(&output, target.u8string()), "cannot create object resource");
711	            const bool written = mz_zip_writer_add_from_zip_reader(&output, &input, entry_index) &&
712	                                 mz_zip_writer_finalize_archive(&output);
713	            close_zip_writer(&output);
714	            require(written, "object resource write is incomplete: " + object.entry);
715	            validate_resource(target, object.resource.entry, object.facets);
716	            sync_file(target);
717	        }
718	        close_zip_reader(&input);
719	        fs::remove(changed_file);
720	    }
721	    for (const ObjectResource& object : capture.version.objects) {
722	        const fs::path path = fs::exists(pending / "new-resources" / (object.resource.id + ".zip")) ?
723	            pending / "new-resources" / (object.resource.id + ".zip") : resource_path(object.resource.id);
724	        require(fs::exists(path), "referenced object resource is missing");
725	    }
726	    checked_write(pending / "manifest.json", version_json(capture.version).dump(2));
727	    sync_file(pending / "metadata.3mf");
728	    sync_directory(pending);
729	    for (const ObjectResource& object : capture.version.objects) {
730	        const fs::path staged = pending / "new-resources" / (object.resource.id + ".zip");
731	        if (fs::exists(staged))
732	            atomic_replace(staged, resource_path(object.resource.id));
733	    }
734	    fs::remove_all(pending / "new-resources");
735	    fs::remove_all(pending / "writer-private");
736	    sync_directory(m_root / "resources");
737	    if (m_publish_stage_hook) m_publish_stage_hook(PublishStage::ResourcesDurable);
738	    sync_directory(pending);
739	    atomic_replace(pending, version_dir(capture.version.id));
740	    if (m_publish_stage_hook) m_publish_stage_hook(PublishStage::VersionPublished);
741	    auto committed = m_committed_ids;
742	    committed.push_back(capture.version.id);
743	    std::map<std::uint64_t, ObjectResource> next_resources;
744	    for (const ObjectResource& object : capture.version.objects)
745	        next_resources[object.object_id] = object;
746	    std::string next_head = capture.version.id;
747	    std::string next_digest = archive_digest(version_dir(capture.version.id) / "metadata.3mf");
748	    checked_write(m_root / "HEAD.pending",
749	                  json{{"schema", 1}, {"current", capture.version.id}, {"versions", committed}}.dump());
750	    replace_file(m_root / "HEAD.pending", m_root / "HEAD");
751	    m_committed_ids.swap(committed);
752	    m_head_id.swap(next_head);
753	    m_last_resources.swap(next_resources);
754	    m_last_signatures = std::move(capture.signatures);
755	    m_last_model = std::move(capture.frozen);
756	    m_last_metadata_digest.swap(next_digest);
757	    m_head_needs_sync = true;
758	    ensure_durable_head();
759	    if (m_publish_stage_hook) m_publish_stage_hook(PublishStage::HeadPublished);
760	}
