   490	void ProjectPersistence::remove_attachment_dir(const std::string& relative_dir)
   491	{
   492	    if (relative_dir.empty())
   493	        return;
   494	    if (m_config.in_memory) {
   495	        for (auto blob = m_blobs.begin(); blob != m_blobs.end();)
   496	            blob = blob->first.rfind(relative_dir, 0) == 0 ? m_blobs.erase(blob) : std::next(blob);
   497	        return;
   498	    }
   499	    if (!m_attached)
   500	        return;
   501	    // Published semantic versions can still reference an attachment after a
   502	    // staged message is removed from the live document. Reachability cleanup
   503	    // belongs to the version store, not this mutable conversation surface.
   504	    if (!m_config.managed_root.empty())
   505	        return;
   506	    std::error_code ec;
   507	    fs::remove_all(fs::path(jusprin_data_dir()) / fs::path(relative_dir), ec);
   508	}
