551	bool ProjectAutosave::resume_latest()
552	{
553	    m_resume_attempted = true;
554	    try {
555	        if (!m_plater.model().objects.empty() || !m_plater.get_project_filename(".3mf").empty() ||
556	            m_persistence.document().doc_revision() > 1)
557	            return false;
558	        std::filesystem::path latest;
559	        std::filesystem::file_time_type latest_time{};
560	        if (!std::filesystem::is_directory(m_root))
561	            return false;
562	        for (const auto& project : std::filesystem::directory_iterator(m_root)) {
563	            if (!project.is_directory() || !std::filesystem::is_regular_file(project.path() / "HEAD"))
564	                continue;
565	            if (m_store && project.path().filename().string() == m_store->project_id())
566	                continue;
567	            try {
568	                if (!authored_head(project.path()))
569	                    continue;
570	            } catch (const std::exception& error) {
571	                BOOST_LOG_TRIVIAL(warning) << "Recent local project index is invalid: " << project.path().string()
572	                                           << ": " << error.what();
573	                continue;
574	            }
575	            auto modified = std::filesystem::last_write_time(project.path() / "HEAD");
576	            if (std::filesystem::is_regular_file(project.path() / "current-state.json"))
577	                modified = std::max(modified, std::filesystem::last_write_time(project.path() / "current-state.json"));
578	            if (latest.empty() || modified > latest_time) {
579	                latest = project.path();
580	                latest_time = modified;
581	            }
582	        }
583	        if (latest.empty())
584	            return false;
585	        // The untouched startup draft has no authored state. Release its
586	        // lock before opening the durable project selected by the store.
587	        settle(true);
588	        m_store.reset();
589	        auto opened = std::make_unique<ProjectVersionStore>(m_root, latest.filename().string());
590	        const std::string head = opened->head_id();
591	        if (head.empty())
592	            throw std::runtime_error("recent managed project has no current version");
593	        const auto materialized = opened->materialize(head);
594	        const auto versions = opened->history();
595	        const auto selected = std::find_if(versions.begin(), versions.end(), [&head](const auto& item) {
596	            return item.id == head;
597	        });
598	        if (selected == versions.end())
599	            throw std::runtime_error("recent managed project has no current manifest");
600	        m_plater.reset();
601	        m_plater.take_snapshot("Resume local project", UndoRedo::SnapshotType::ProjectSeparator);
602	        auto strategy = LoadStrategy::Restore;
603	        if (materialized.empty)
604	            strategy = strategy | LoadStrategy::AllowEmpty;
605	        const auto loaded = m_plater.load_files(
606	            std::vector<boost::filesystem::path>{boost_path(materialized.metadata),
607	                                                 boost_path(materialized.absent_original)},
608	            strategy, false);
609	        if ((loaded.empty() && !materialized.empty) || (materialized.empty && !m_plater.model().objects.empty()))
610	            throw std::runtime_error("recent managed project could not be restored");

