178	std::string archive_digest(const fs::path& path)
179	{
180	    mz_zip_archive zip;
181	    mz_zip_zero_struct(&zip);
182	    require(open_zip_reader(&zip, path.u8string()), "cannot read project metadata digest");
183	    std::map<std::string, std::pair<mz_uint32, mz_uint64>> entries;
184	    for (mz_uint index = 0; index < mz_zip_reader_get_num_files(&zip); ++index) {
185	        mz_zip_archive_file_stat stat;
186	        require(mz_zip_reader_file_stat(&zip, index, &stat), "cannot inspect project metadata entry");
187	        entries[stat.m_filename] = {stat.m_crc32, stat.m_uncomp_size};
188	    }
189	    close_zip_reader(&zip);
190	    std::ostringstream digest;
191	    for (const auto& [name, values] : entries)
192	        digest << name << '\t' << values.first << '\t' << values.second << '\n';
193	    return digest.str();
194	}
