197	{
198	    std::set<std::string> paths;
199	    const char* element{nullptr};
200	    const char* attribute{nullptr};
201	};
202	
203	void XMLCALL collect_path(void* user, const XML_Char* element, const XML_Char** attributes)
204	{
205	    auto& result = *static_cast<XmlPaths*>(user);
206	    if (std::strcmp(element, result.element) != 0)
207	        return;
208	    for (const XML_Char** attribute = attributes; *attribute != nullptr; attribute += 2)
209	        if (std::strcmp(attribute[0], result.attribute) == 0)
210	            result.paths.emplace(attribute[1]);
211	}
