213	std::set<std::string> archive_xml_paths(const fs::path& path, const char* zip_entry,
214	                                        const char* element, const char* attribute)
215	{
216	    mz_zip_archive zip;
217	    mz_zip_zero_struct(&zip);
218	    require(open_zip_reader(&zip, path.u8string()), "cannot open project metadata");
219	    std::size_t size = 0;
220	    void* data = mz_zip_reader_extract_file_to_heap(&zip, zip_entry, &size, 0);
221	    close_zip_reader(&zip);
222	    require(data != nullptr, std::string("project metadata is missing ") + zip_entry);
223	    XmlPaths paths;
224	    paths.element = element;
225	    paths.attribute = attribute;
226	    XML_Parser parser = XML_ParserCreate(nullptr);
227	    require(parser != nullptr, "cannot create metadata XML parser");
228	    XML_SetUserData(parser, &paths);
229	    XML_SetStartElementHandler(parser, collect_path);
230	    const bool valid = size <= static_cast<std::size_t>(std::numeric_limits<int>::max()) &&
231	                       XML_Parse(parser, static_cast<const char*>(data), static_cast<int>(size), true) == XML_STATUS_OK;
232	    XML_ParserFree(parser);
233	    mz_free(data);
234	    require(valid, std::string("project metadata XML is invalid: ") + zip_entry);
235	    return paths.paths;
236	}
