5928	    bool _BBS_3MF_Exporter::save_model_to_file(StoreParams& store_params)
5929	    {
5930	        clear_errors();
5931	        m_fullpath_sources = store_params.strategy & SaveStrategy::FullPathSources;
5932	        m_zip64 = store_params.strategy & SaveStrategy::Zip64;
5933	        m_production_ext = store_params.strategy & SaveStrategy::ProductionExt;
5934	
5935	        m_skip_static = store_params.strategy & SaveStrategy::SkipStatic;
5936	        m_split_model = store_params.strategy & SaveStrategy::SplitModel;
5937	        m_save_gcode = store_params.strategy & SaveStrategy::WithGcode;
5938	        m_skip_model  = store_params.strategy & SaveStrategy::SkipModel;
5939	        m_skip_auxiliary = store_params.strategy & SaveStrategy::SkipAuxiliary;
5940	        m_share_mesh       = store_params.strategy & SaveStrategy::ShareMesh;
5941	        m_from_backup_save = store_params.strategy & SaveStrategy::Backup;
5942	
5943	        m_use_loaded_id = store_params.strategy & SaveStrategy::UseLoadedId;
5944	
5945	        if (auto info = store_params.model->model_info) {
5946	            if (auto iter = info->metadata_items.find("Thumbnail_Small"); iter != info->metadata_items.end())
5947	                m_thumbnail_small = iter->second;
5948	            if (auto iter = info->metadata_items.find("Thumbnail_Middle"); iter != info->metadata_items.end())
5949	                m_thumbnail_middle = iter->second;
5950	        }
5951	        boost::system::error_code ec;
5952	        std::string filename = std::string(store_params.path);
5953	        boost::filesystem::remove(filename + ".tmp", ec);
5954	
5955	        bool result = _save_model_to_file(filename + ".tmp", *store_params.model, store_params.plate_data_list, store_params.project_presets, store_params.config,
5956	                                          store_params.thumbnail_data, store_params.no_light_thumbnail_data, store_params.top_thumbnail_data, store_params.pick_thumbnail_data,
5957	                                          store_params.proFn,
5958	            store_params.calibration_thumbnail_data, store_params.id_bboxes, store_params.project, store_params.export_plate_idx);
5959	        if (result) {
5960	            boost::filesystem::rename(filename + ".tmp", filename, ec);
5961	            if (ec) {
5962	                add_error("Failed to rename file: " + ec.message());
5963	                boost::filesystem::remove(filename + ".tmp", ec);
5964	                return false;
5965	            }
5966	            if (!(store_params.strategy & SaveStrategy::Silence))
5967	                save_string_file(store_params.model->get_backup_path() + "/origin.txt", filename);
5968	        }
5969	        return result;
5970	    }
