5973	    bool _BBS_3MF_Exporter::save_object_mesh(const std::string& temp_path, ModelObject const & object, int obj_id)
5974	    {
5975	        m_production_ext = true;
5976	        m_from_backup_save = true;
5977	        Model const & model = *object.get_model();
5978	
5979	        mz_zip_archive archive;
5980	        mz_zip_zero_struct(&archive);
5981	
5982	        auto filename = boost::format("3D/Objects/%s_%d.model") % object.name % obj_id;
5983	        std::string filepath = temp_path + "/" + filename.str();
5984	        std::string filepath_tmp = filepath + ".tmp";
5985	        boost::system::error_code ec;
5986	        boost::filesystem::remove(filepath_tmp, ec);
5987	        if (!open_zip_writer(&archive, filepath_tmp)) {
5988	            add_error("Unable to open the file"+filepath_tmp);
5989	            BOOST_LOG_TRIVIAL(error) << __FUNCTION__ << ":" << __LINE__ << boost::format(", Unable to open the file\n");
5990	            return false;
5991	        }
5992	
5993	        struct close_lock
5994	        {
5995	            mz_zip_archive & archive;
5996	            std::string const * filename;
5997	            void close() {
5998	                close_zip_writer(&archive);
5999	                filename = nullptr;
6000	            }
6001	            ~close_lock() {
6002	                if (filename) {
6003	                    close_zip_writer(&archive);
6004	                    boost::system::error_code ec;
6005	                    boost::filesystem::remove(*filename, ec);
6006	                }
6007	            }
6008	        } lock{archive, &filepath_tmp};
6009	
6010	        ObjectToObjectDataMap objects_data;
6011	        auto & volumes_objectID = objects_data.insert({&object, {&object, obj_id}}).first->second.volumes_objectID;
6012	        unsigned int volume_count = 0;
6013	        for (ModelVolume *volume : object.volumes) {
6014	            if (volume == nullptr) continue;
6015	            volumes_objectID.insert({volume, (++volume_count << 16 | obj_id)});
6016	        }
6017	
6018	        _add_model_file_to_archive(filename.str(), archive, model, objects_data);
6019	
6020	        mz_zip_writer_finalize_archive(&archive);
6021	        lock.close();
6022	        boost::filesystem::rename(filepath_tmp, filepath, ec);
6023	        return true;
6024	    }
