864	void ProjectVersionStore::prune(std::size_t max_versions, std::uintmax_t max_bytes,
865	                                const std::set<std::string>& live_attachments)
866	{
867	    require(max_versions >= 1 && max_bytes > 0, "invalid retention budget");
868	    std::set<std::string> protected_ids{m_head_id};
869	    if (fs::exists(m_root / "pins.json"))
870	        for (const json& item : json::parse(read_file(m_root / "pins.json")))
871	            protected_ids.insert(item.get<std::string>());
872	    for (const auto& entry : fs::directory_iterator(m_root / "operations")) {
873	        if (!entry.is_regular_file() || entry.path().extension() != ".json")
874	            continue;
875	        const json operation = json::parse(read_file(entry.path()));
876	        for (const char* field : {"before", "after"}) {
877	            const std::string id = operation.value(field, "");
878	            if (!id.empty()) protected_ids.insert(id);
879	        }
880	    }
881	    auto versions = history();
882	    const auto reachable_files = [this, &live_attachments](const std::vector<Version>& retained) {
883	        std::set<std::string> resources;
884	        std::set<std::string> attachments = live_attachments;
885	        if (!m_last_semantic_state.empty()) {
886	            const auto current_paths = attachment_paths(m_last_semantic_state);
887	            attachments.insert(current_paths.begin(), current_paths.end());
888	        }
889	        std::uintmax_t bytes = 0;
890	        for (const Version& version : retained) {
891	            for (const auto& entry : fs::recursive_directory_iterator(version_dir(version.id)))
892	                if (entry.is_regular_file()) bytes += entry.file_size();
893	            for (const ObjectResource& object : version.objects)
894	                resources.insert(object.resource.id);
895	            if (fs::exists(version_dir(version.id) / "state.json")) {
896	                const auto paths = attachment_paths(read_file(version_dir(version.id) / "state.json"));
897	                attachments.insert(paths.begin(), paths.end());
898	            }
899	        }
900	        for (const std::string& id : resources)
901	            bytes += fs::file_size(resource_path(id));
902	        for (const std::string& path : attachments)
903	            if (fs::exists(m_root / fs::u8path(path)))
904	                bytes += fs::file_size(m_root / fs::u8path(path));
