493	{
494	    try {
495	        if (!m_resume_attempted) {
496	            GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
497	            if (canvas == nullptr || !canvas->is_initialized())
498	                return;
499	            resume_latest();
500	        }
501	        adopt_project();
502	        if (!settle(false) && m_worker.valid())
503	            return;
504	        observe_document_change();
505	        const auto now = Clock::now();
506	        if (now < m_next_probe)
507	            return;
508	        m_next_probe = now + kProbeInterval;
509	        if (m_plater.model().objects.empty() && m_store->head_id().empty() &&
510	            m_persistence.document().doc_revision() <= 1) {
511	            m_state = State::Saved;
512	            return;
513	        }
514	        const std::string model_input = observed_input();
515	        if (model_input != m_seen_model_input) {
516	            m_seen_model_input = model_input;
517	            m_last_edit = now;
518	            m_state = State::Saving;
519	        }
520	        const bool document_pending = m_persistence.document().doc_revision() != m_committed_semantic_revision;
521	        const bool document_due = document_pending &&
522	            (now - m_last_semantic_edit >= kEditQuietPeriod ||
523	             (m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay));
524	        // A continuously edited model must not starve the current document.
525	        // Model capture also publishes the document, so a ready model still
526	        // takes precedence until the document's maximum delay is reached.
527	        if (document_due && m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay) {
528	            persist_document(false);
529	            return;
530	        }
531	        if (m_store->head_id().empty() || model_input != m_last_capture_input) {
532	            GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
533	            if (canvas == nullptr || !canvas->is_initialized() ||
534	                canvas->get_gizmos_manager().is_in_editing_mode(true) ||
535	                now - m_last_edit < kEditQuietPeriod)
536	                return;
537	            capture(false);
538	        } else if (document_pending) {
539	            if (!document_due)
540	                return;
541	            persist_document(false);
542	        } else {
543	            m_state = State::Saved;
544	            m_first_semantic_edit.reset();
545	        }
