   883	        std::set<std::string> resources;
   884	        std::set<std::string> attachments = live_attachments;
   885	        if (!m_last_semantic_state.empty()) {
   886	            const auto current_paths = attachment_paths(m_last_semantic_state);
   887	            attachments.insert(current_paths.begin(), current_paths.end());
   888	        }
   889	        std::uintmax_t bytes = 0;
   890	        for (const Version& version : retained) {
   891	            for (const auto& entry : fs::recursive_directory_iterator(version_dir(version.id)))
   892	                if (entry.is_regular_file()) bytes += entry.file_size();
   893	            for (const ObjectResource& object : version.objects)
   894	                resources.insert(object.resource.id);
   895	            if (fs::exists(version_dir(version.id) / "state.json")) {
   896	                const auto paths = attachment_paths(read_file(version_dir(version.id) / "state.json"));
   897	                attachments.insert(paths.begin(), paths.end());
   898	            }
   899	        }
   900	        for (const std::string& id : resources)
   901	            bytes += fs::file_size(resource_path(id));
